package provisioning

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/BeppeTemp/cartographer/internal/configurator"
	"github.com/BeppeTemp/cartographer/internal/safewrite"
)

// Cline hooks. The VS Code extension runs, per event, the one file named after
// it in Documents/Cline/Hooks (<Event> on POSIX, <Event>.ps1 on Windows), for
// every extension of every KB alike; $HOME/.cline/hooks is not read by it. So
// Pi's model (one generated file per hook) would collide: Cartographer writes
// ONE dispatcher per needed event, a thin shim for `cartographer hook dispatch`
// (clinedispatch.go), and the hooks' own files stay under clineHookFilesPrefix.
//
// Ownership is the clineDispatcherMarker token in the file's first bytes, never
// a lock entry: a dispatcher is needed by every hook of its event, so the set
// of dispatchers is derived from the hooks on disk (reconcileClineDispatchers)
// and a hook's prune cannot delete what another hook still uses. A file of the
// user's at that path is never rewritten, read past its head, merged or
// deleted: the hooks are installed, not wired, and the sync says so. This is
// the one write outside the client base dir's own layout (the Documents folder,
// clineDocumentsDir is the only place that may leave it) and, since nothing in
// the bundle identifies the client, the file is shared by every Cline build.

// clineDispatcherMarker is the ownership token of a dispatcher file.
const clineDispatcherMarker = "cartographer:cline-hook-dispatcher"

// ClineDispatcherCommand finds the cartographer binary a dispatcher calls by
// absolute path. provisioning cannot import cmd, which assigns bridgeCommand
// here (PATH lookup, never os.Executable(): a Homebrew Cellar path is deleted by
// the next upgrade).
var ClineDispatcherCommand = func() (string, error) {
	return exec.LookPath("cartographer")
}

func clineHooksDir(baseDir string) string {
	return filepath.Join(clineDocumentsDir(baseDir), "Cline", "Hooks")
}

func clineDispatcherPath(baseDir, event string) string {
	name := event
	if hookHostWindows {
		name += ".ps1"
	}
	return filepath.Join(clineHooksDir(baseDir), name)
}

// generateClineDispatcher renders the shim of one event: fail-open (a missing
// binary prints {} and exits 0), the payload reaches cartographer by stdin
// inheritance, the exit status is always 0.
func generateClineDispatcher(event, bin string, windows bool) []byte {
	head := "# " + clineDispatcherMarker + " " + event + " - generated by Cartographer, do not edit.\n"
	if windows {
		// UTF-8 with BOM: Windows PowerShell 5.1 reads BOM-less UTF-8 as ANSI and
		// would corrupt a non-ASCII user name in the path. No `&&`, no ternary.
		q := "'" + psSingleQuoteDoubler.Replace(bin) + "'"
		return []byte("\xef\xbb\xbf" + head +
			"$cartographer = " + q + "\n" +
			"if (-not (Test-Path -LiteralPath $cartographer)) { '{}'; exit 0 }\n" +
			"& $cartographer hook dispatch --provider cline --event " + event + "\n" +
			"exit 0\n")
	}
	q := "'" + strings.ReplaceAll(bin, "'", `'\''`) + "'"
	return []byte("#!/bin/sh\n" + head +
		"[ -x " + q + " ] || { echo '{}'; exit 0; }\n" +
		q + " hook dispatch --provider cline --event " + event + "\n" +
		"exit 0\n")
}

// psSingleQuoteDoubler escapes a PowerShell single-quoted string: besides the
// ASCII quote, PowerShell treats U+2018, U+2019, U+201A and U+201B as quotes
// too, and each is doubled the same way.
var psSingleQuoteDoubler = strings.NewReplacer("'", "''", "\u2018", "\u2018\u2018", "\u2019", "\u2019\u2019", "\u201a", "\u201a\u201a", "\u201b", "\u201b\u201b")

// clineOwnership classifies what is at a dispatcher path.
type clineOwnership int

const (
	clineAbsent  clineOwnership = iota
	clineOwned                  // a regular file carrying the marker
	clineForeign                // anything else: a user's file, a directory, a link
)

func clineOwner(path string) clineOwnership {
	fi, err := os.Lstat(path)
	if err != nil {
		return clineAbsent
	}
	if !fi.Mode().IsRegular() {
		return clineForeign
	}
	f, err := os.Open(path)
	if err != nil {
		return clineForeign
	}
	defer f.Close()
	head, _ := io.ReadAll(io.LimitReader(f, 512)) // never read past the head of a file that may be the user's
	if bytes.Contains(bytes.TrimPrefix(head, []byte("\xef\xbb\xbf")), []byte(clineDispatcherMarker)) {
		return clineOwned
	}
	return clineForeign
}

// clineHookDirOf is the hook directory (slash, relative to baseDir) a file of a
// hook belongs to: the root the path lies under plus the next segment. Empty when
// no registered root holds it (a variant that left the registry).
func clineHookDirOf(relPath string) string {
	p := filepath.ToSlash(relPath)
	for _, root := range clineHookRoots() {
		if rest, ok := strings.CutPrefix(p, root+"/"); ok {
			name, _, _ := strings.Cut(rest, "/")
			return root + "/" + name
		}
	}
	return ""
}

// reconcileClineDispatchers makes the dispatchers match the hooks on disk, the
// one code path of the bootstrap, write-findings and KB hooks whatever their
// order: every needed event gets its dispatcher created or, when it is ours and
// differs, rewritten (the mode is kept: on POSIX the exec bit is the user's
// per-hook toggle in Cline's UI); every other event loses its dispatcher, only
// if it still carries the marker, and no folder is ever removed. An event whose
// path safewrite refuses (a link) is reported and left untouched. A needed event whose path is not ours is
// reported in the returned map and left untouched. exclude is a hook being
// removed (its directory, see clineHooks), whose hook.json is still on disk.
func reconcileClineDispatchers(baseDir, exclude string) (warnings map[string]string, err error) {
	needed := map[string]bool{}
	for _, h := range clineHooks(baseDir, exclude) {
		needed[h.clineEvent] = true
	}
	warnings = map[string]string{}
	// The Documents folder is the root of every write below, not the base dir: it
	// may be a redirected Windows folder outside it, or a link of the user's own
	// (exempt as a root), while a link at Cline or Cline/Hooks is refused.
	docs := clineDocumentsDir(baseDir)
	var bin string
	var binErr error
	if len(needed) > 0 {
		bin, binErr = ClineDispatcherCommand()
		if binErr == nil {
			bin, binErr = filepath.Abs(bin)
		}
	}
	for _, event := range clineEventNames {
		path := clineDispatcherPath(baseDir, event)
		// A link (or another non-plain path) at Cline, Cline/Hooks or the file is a
		// safewrite refusal, in its words: a warning, never an error that would
		// abort the reconcile and repeat on every sync. Nothing is touched.
		owner := clineOwner(path)
		if !needed[event] && owner != clineOwned {
			continue // nothing of ours to remove, nothing to report
		}
		if err := safewrite.CheckPath(docs, path); err != nil {
			if needed[event] {
				warnings[event] = fmt.Sprintf("cline: the %s hooks of this KB were installed but not wired: %v", event, err)
			} else {
				warnings[event] = fmt.Sprintf("cline: the %s dispatcher was left in place: %v", event, err)
			}
			continue
		}
		if !needed[event] {
			if err := safewrite.Remove(docs, path); err != nil && !errors.Is(err, os.ErrNotExist) {
				return warnings, fmt.Errorf("provisioning: remove Cline dispatcher %s: %w", path, err)
			}
			// No directory is removed: Documents/Cline/Hooks belongs to the extension.
			continue
		}
		switch {
		case binErr != nil:
			warnings[event] = fmt.Sprintf("cline: the %s hooks need cartographer on PATH to be wired (%v)", event, binErr)
		case owner == clineForeign:
			warnings[event] = fmt.Sprintf("cline: %s already exists and is not Cartographer's; the %s hooks of this KB were installed but not wired (rename or move that file, then sync)", path, event)
		default:
			if err := mkdirAllNoFollow(docs, filepath.Dir(path), 0o755); err != nil {
				return warnings, fmt.Errorf("provisioning: mkdir %s: %w", filepath.Dir(path), err)
			}
			if err := writeFileAtomicNoFollow(docs, path, generateClineDispatcher(event, bin, hookHostWindows), 0o755); err != nil {
				return warnings, fmt.Errorf("provisioning: write Cline dispatcher %s: %w", path, err)
			}
		}
	}
	return warnings, nil
}

// registerClineHook wires hookName: its files are already in fullDestDir, so
// the dispatchers are reconciled from disk. relPath is always empty, the
// dispatcher is not a managed file.
func registerClineHook(baseDir, hookName, fullDestDir string) (relPath, warning string, registered bool, err error) {
	spec, specErr := loadHookSpec(fullDestDir)
	if specErr != nil {
		return "", hookSpecWarning(hookName, configurator.ProviderCline, specErr), false, nil
	}
	if w, skip := hookEventWarning(hookName, configurator.ProviderCline, spec.Event); skip {
		return "", w, false, nil
	}
	event, ok := clineHookEvents[spec.Event]
	if !ok {
		return "", fmt.Sprintf("hook %q: cline: event %q has no Cline equivalent; files were installed but the hook was not registered", hookName, spec.Event), false, nil
	}
	if m := strings.TrimSpace(spec.Matcher); m != "" && spec.Event != "SessionStart" {
		if h := clineHooks(baseDir, ""); !hasClineHook(h, fullDestDir) {
			return "", fmt.Sprintf("hook %q: cline: matcher %q is not a valid regular expression; files were installed but the hook was not registered", hookName, spec.Matcher), false, nil
		}
	}
	warnings, err := reconcileClineDispatchers(baseDir, "")
	if err != nil {
		return "", "", false, err
	}
	if w := warnings[event]; w != "" {
		return "", fmt.Sprintf("hook %q: %s", hookName, w), false, nil
	}
	return "", "", true, nil
}

func hasClineHook(hooks []clineHook, dir string) bool {
	for _, h := range hooks {
		if h.dir == dir {
			return true
		}
	}
	return false
}

// removeClineHook runs before the hook's files go (removeHookRegistration), so
// its hook.json is still on disk: reconcile without it.
func removeClineHook(baseDir, hookName string) error {
	return removeClineHookAt(baseDir, clineHookFilesPrefix+hookName+"/hook.json")
}

// removeClineHookAt is removeClineHook for a file of the hook at relPath: only
// that root's hook of the name is left out, so a Cline hook of the same name in
// another root keeps its dispatcher.
func removeClineHookAt(baseDir, relPath string) error {
	_, err := reconcileClineDispatchers(baseDir, clineHookDirOf(relPath))
	return err
}
